INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '我们一起看电影，怎么样？', 'Wǒmen yìqǐ kàn diànyǐng, zěnmeyàng?', 'Chúng ta cùng xem phim nhé, thế nào?', 3);
