INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 9, 1, '林娜', '这个星期天你忙不忙？', 'Zhège xīngqītiān nǐ máng bu máng?', 'Chủ nhật này bạn có bận không?', 0);
