INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 18, 'Phó từ 只好 - đành phải', '暖气坏了，我们只好穿多点儿衣服。', 'Lò sưởi hỏng rồi, chúng tôi đành phải mặc nhiều quần áo hơn.', 0);
