INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 18, 'Lượng từ động lượng 遍', '我打了三遍电话。', 'Tôi đã gọi điện ba lần.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 18, '暖气还没有修好。', 'Nuǎnqì hái méiyǒu xiūhǎo.', 'Lò sưởi vẫn chưa sửa xong.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 18, '房间里很冷。', 'Fángjiān lǐ hěn lěng.', 'Trong phòng rất lạnh.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 18, '我给师傅打了两遍电话。', 'Wǒ gěi shīfu dǎle liǎng biàn diànhuà.', 'Tôi đã gọi điện cho thợ hai lần.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 18, '暖气坏了，我们只好去图书馆学习。', 'Nuǎnqì huàile, wǒmen zhǐhǎo qù túshūguǎn xuéxí.', 'Lò sưởi hỏng rồi, chúng tôi đành phải đi thư viện học.', 3);
