INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 18, 1, '马丁', '房间里怎么这么冷？', 'Fángjiān lǐ zěnme zhème lěng?', 'Sao trong phòng lạnh vậy?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 18, 1, '林娜', '暖气坏了，还没有修好。', 'Nuǎnqì huàile, hái méiyǒu xiūhǎo.', 'Lò sưởi hỏng rồi, vẫn chưa sửa xong.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 18, 1, '马丁', '打电话叫师傅来修吧。', 'Dǎ diànhuà jiào shīfu lái xiū ba.', 'Gọi điện gọi thợ đến sửa đi.', 2);
