INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 19, 'Bổ ngữ kết quả (2): V+到', '快餐可以送到家里。', 'Đồ ăn nhanh có thể giao đến tận nhà.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 19, '又...又... - vừa...vừa...', '这家快餐又便宜又方便。', 'Đồ ăn nhanh ở đây vừa rẻ vừa tiện.', 1);
