INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 19, '快餐可以送到家里。', 'Kuàicān kěyǐ sòngdào jiā lǐ.', 'Đồ ăn nhanh có thể giao đến tận nhà.', 0);
