INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 19, '大概三十分钟能送到。', 'Dàgài sānshí fēnzhōng néng sòngdào.', 'Khoảng ba mươi phút là giao đến.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 19, '点外卖又方便又快。', 'Diǎn wàimài yòu fāngbiàn yòu kuài.', 'Gọi đồ ăn giao hàng vừa tiện vừa nhanh.', 3);
