INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 19, 1, '崔浩', '我们点外卖吧，快餐可以送到家里。', 'Wǒmen diǎn wàimài ba, kuàicān kěyǐ sòngdào jiā lǐ.', 'Chúng ta gọi đồ ăn giao hàng đi, đồ ăn nhanh có thể giao đến tận nhà.', 0);
