INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 27, '长城有八千八百五十多公里。', 'Chángchéng yǒu bāqiān bābǎi wǔshí duō gōnglǐ.', 'Vạn Lý Trường Thành dài hơn 8850km.', 0);
