INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 27, '长城是古代建的。', 'Chángchéng shì gǔdài jiàn de.', 'Trường Thành được xây từ thời cổ đại.', 2);
