INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 27, 1, '马丁', '长城有多长？', 'Chángchéng yǒu duō cháng?', 'Trường Thành dài bao nhiêu?', 0);
