INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 30, '一个人到了新的地方，要入乡随俗。', 'Yí ge rén dàole xīn de dìfang, yào rù xiāng suí sú.', 'Một người đến nơi mới thì phải nhập gia tùy tục.', 0);
