INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 30, '为了不迟到，我每天都定闹钟。', 'Wèile bù chídào, wǒ měitiān dōu dìng nàozhōng.', 'Để không đến muộn, mỗi ngày tôi đều đặt báo thức.', 3);
