INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 30, 1, '阿明', '对不起，我迟到了。', 'Duìbuqǐ, wǒ chídào le.', 'Xin lỗi, tôi đến muộn rồi.', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 30, 1, '老师', '没关系，你要入乡随俗，每天早点儿起床。', 'Méi guānxi, nǐ yào rù xiāng suí sú, měitiān zǎodiǎnr qǐchuáng.', 'Không sao, em nên nhập gia tùy tục, mỗi ngày dậy sớm hơn.', 1);
