INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 31, 'Nơi chốn+V+着+N (câu tồn tại)', '机场站着很多接机的人。', 'Ở sân bay đứng rất nhiều người đón khách.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 31, '儿子要回家了，妈妈很激动。', 'Érzi yào huíjiā le, māma hěn jīdòng.', 'Con trai sắp về nhà rồi, mẹ rất xúc động.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 31, '我从来没有这么想家过。', 'Wǒ cónglái méiyǒu zhème xiǎngjiā guo.', 'Tôi chưa bao giờ nhớ nhà đến thế.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 31, '爸爸去机场接儿子。', 'Bàba qù jīchǎng jiē érzi.', 'Bố đi sân bay đón con trai.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 31, '放假了，全家终于可以团聚了。', 'Fàngjià le, quánjiā zhōngyú kěyǐ tuánjù le.', 'Nghỉ lễ rồi, cả nhà cuối cùng cũng có thể sum họp.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 31, '儿子要回家', 'érzi yào huíjiā', 'con trai sắp về nhà', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 31, '从来没有', 'cónglái méiyǒu', 'từ trước đến nay chưa từng', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 31, '全家团聚', 'quánjiā tuánjù', 'cả nhà sum họp', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 31, 1, '妈妈', '儿子明天就要回家了，我好激动！', 'Érzi míngtiān jiù yào huíjiā le, wǒ hǎo jīdòng!', 'Ngày mai con trai về nhà rồi, mẹ xúc động quá!', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 31, 1, '爸爸', '我明天去机场接他。', 'Wǒ míngtiān qù jīchǎng jiē tā.', 'Ngày mai tôi đi sân bay đón nó.', 1);
