INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 32, 'Bổ ngữ xu hướng phức hợp', '她把辣椒搬进来了。', 'Cô ấy đã mang ớt vào.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 32, '既...也/又... - vừa...vừa...', '她既聪明又勤劳。', 'Cô ấy vừa thông minh vừa chăm chỉ.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 32, '把+O+V+bổ ngữ xu hướng', '她把辣椒拿出来了。', 'Cô ấy đã lấy ớt ra.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 32, '市场上有一个卖辣椒的女孩儿。', 'Shìchǎng shàng yǒu yí ge mài làjiāo de nǚháir.', 'Ở chợ có một cô gái bán ớt.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 32, '她的辣椒很新鲜。', 'Tā de làjiāo hěn xīnxiān.', 'Ớt của cô ấy rất tươi.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 32, '她既聪明又勤劳，生意很好。', 'Tā jì cōngming yòu qínláo, shēngyi hěn hǎo.', 'Cô ấy vừa thông minh vừa chăm chỉ, buôn bán rất tốt.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 32, '这斤辣椒多少钱？', 'Zhè jīn làjiāo duōshao qián?', 'Cân ớt này bao nhiêu tiền?', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 32, '卖辣椒', 'mài làjiāo', 'bán ớt', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 32, '既聪明又勤劳', 'jì cōngming yòu qínláo', 'vừa thông minh vừa chăm chỉ', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 32, '生意很好', 'shēngyi hěn hǎo', 'buôn bán rất tốt', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 32, 1, '顾客', '这辣椒新鲜吗？多少钱一斤？', 'Zhè làjiāo xīnxiān ma? Duōshao qián yì jīn?', 'Ớt này có tươi không? Bao nhiêu tiền một cân?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 32, 1, '卖辣椒的女孩儿', '很新鲜，三块钱一斤。', 'Hěn xīnxiān, sān kuài qián yì jīn.', 'Rất tươi, ba đồng một cân.', 1);
