INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 33, '其实', 'qíshí', 'thực ra', 'actually', 3);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 33, '机会', 'jīhuì', 'cơ hội', 'opportunity', 4);
