INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 33, '留学', 'liúxué', 'du học', 'to study abroad', 9);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 33, 'Câu 是...的 (1)', '我是去年来中国的。', 'Tôi đến Trung Quốc từ năm ngoái.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 33, '不但...而且... - không những...mà còn...', '他不但喜欢中国文化，而且会说汉语。', 'Anh ấy không những thích văn hóa Trung Quốc, mà còn biết nói tiếng Hán.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 33, '其实 - thực ra', '其实我一直想来中国留学。', 'Thực ra tôi luôn muốn đến Trung Quốc du học.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 33, '我和中国有个约会。', 'Wǒ hé Zhōngguó yǒu ge yuēhuì.', 'Tôi có một cuộc hẹn với Trung Quốc.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 33, '这是我实现梦想的机会。', 'Zhè shì wǒ shíxiàn mèngxiǎng de jīhuì.', 'Đây là cơ hội để tôi thực hiện ước mơ.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 33, '我决定来中国留学。', 'Wǒ juédìng lái Zhōngguó liúxué.', 'Tôi quyết định đến Trung Quốc du học.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 33, '中国文化不但有意思，而且很丰富。', 'Zhōngguó wénhuà búdàn yǒuyìsi, érqiě hěn fēngfù.', 'Văn hóa Trung Quốc không những thú vị mà còn rất phong phú.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 33, '有个约会', 'yǒu ge yuēhuì', 'có một cuộc hẹn', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 33, '实现梦想', 'shíxiàn mèngxiǎng', 'thực hiện ước mơ', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 33, '决定留学', 'juédìng liúxué', 'quyết định du học', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 33, 1, '朱云', '你为什么决定来中国留学？', 'Nǐ wèishénme juédìng lái Zhōngguó liúxué?', 'Vì sao bạn quyết định đến Trung Quốc du học?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 33, 1, '林娜', '其实，我和中国一直有个约会——这是我的梦想。', 'Qíshí, wǒ hé Zhōngguó yìzhí yǒu ge yuēhuì — zhè shì wǒ de mèngxiǎng.', 'Thực ra, tôi và Trung Quốc luôn có một cuộc hẹn — đó là ước mơ của tôi.', 1);
