INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 34, '满', 'mǎn', 'đầy', 'full', 9);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 34, 'V1+着+V2 - vừa...vừa...', '他站着吃早饭。', 'Anh ấy đứng ăn sáng.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 34, 'Từ nghi vấn+也/都... (bất kể)', '哪儿都没有座位。', 'Chỗ nào cũng không có chỗ ngồi.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 34, '为什么我一个人站着吃？', 'Wèishénme wǒ yí ge rén zhànzhe chī?', 'Vì sao tôi đứng ăn một mình?', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 34, '餐厅里的座位都满了。', 'Cāntīng lǐ de zuòwèi dōu mǎn le.', 'Chỗ ngồi trong nhà hàng đã đầy hết rồi.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 34, '这个习俗很奇怪，但是也有原因。', 'Zhège xísú hěn qíguài, dànshì yě yǒu yuányīn.', 'Phong tục này khá lạ, nhưng cũng có nguyên nhân.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 34, '你能给我解释一下吗？', 'Nǐ néng gěi wǒ jiěshì yíxià ma?', 'Bạn có thể giải thích cho tôi một chút không?', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 34, '站着吃', 'zhànzhe chī', 'đứng ăn', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 34, '座位满了', 'zuòwèi mǎn le', 'chỗ ngồi đầy rồi', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 34, '解释一下', 'jiěshì yíxià', 'giải thích một chút', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 34, 1, '马丁', '为什么我一个人站着吃？这里没有座位吗？', 'Wèishénme wǒ yí ge rén zhànzhe chī? Zhèlǐ méiyǒu zuòwèi ma?', 'Vì sao tôi phải đứng ăn một mình? Ở đây không có chỗ ngồi à?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 34, 1, '李一民', '今天人太多，座位都满了，这也是这儿的习俗。', 'Jīntiān rén tài duō, zuòwèi dōu mǎn le, zhè yě shì zhèr de xísú.', 'Hôm nay đông người quá, chỗ ngồi đầy hết rồi, đây cũng là phong tục ở đây.', 1);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 35, '一切', 'yíqiè', 'tất cả, mọi thứ', 'everything', 0);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 35, '越', 'yuè', 'càng', 'the more', 1);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 35, '适应', 'shìyìng', 'thích nghi', 'to adapt', 2);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 35, '独立', 'dúlì', 'độc lập', 'independent', 3);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 35, '照顾', 'zhàogù', 'chăm sóc', 'to take care of', 4);
