INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 35, '越来越', 'yuè lái yuè', 'càng ngày càng', 'more and more', 7);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 35, '写信', 'xiěxìn', 'viết thư', 'to write a letter', 8);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 35, '报平安', 'bào píng''ān', 'báo bình an', 'to report safety', 9);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 35, '越A越B - càng...càng...', '我越来越适应这里的生活了。', 'Tôi càng ngày càng thích nghi với cuộc sống ở đây.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 35, 'V+得/不+kết quả/xu hướng (khả năng bổ ngữ 1)', '我一个人照顾得了自己。', 'Tôi có thể tự chăm sóc bản thân một mình.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 35, '妈妈，我这里一切都好，请放心。', 'Māma, wǒ zhèlǐ yíqiè dōu hǎo, qǐng fàngxīn.', 'Mẹ ơi, ở đây con mọi thứ đều tốt, mẹ yên tâm nhé.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 35, '我越来越适应这里的生活了。', 'Wǒ yuè lái yuè shìyìng zhèlǐ de shēnghuó le.', 'Con càng ngày càng thích nghi với cuộc sống ở đây.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 35, '不要担心我，我能照顾好自己。', 'Búyào dānxīn wǒ, wǒ néng zhàogù hǎo zìjǐ.', 'Đừng lo cho con, con có thể tự chăm sóc tốt bản thân.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 35, '我会常常写信报平安的。', 'Wǒ huì chángcháng xiěxìn bào píng''ān de.', 'Con sẽ thường xuyên viết thư báo bình an.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 35, '一切都好', 'yíqiè dōu hǎo', 'mọi thứ đều tốt', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 35, '越来越适应', 'yuè lái yuè shìyìng', 'càng ngày càng thích nghi', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 35, '照顾好自己', 'zhàogù hǎo zìjǐ', 'tự chăm sóc tốt bản thân', 2);
