INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 36, 'V/Adj+起来 - bắt đầu...', '他一提到埃及就兴奋起来。', 'Anh ấy vừa nhắc đến Ai Cập liền phấn khích hẳn lên.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 36, 'V/Adj+下去 - tiếp tục...', '这个计划我们要坚持下去。', 'Kế hoạch này chúng ta phải kiên trì tiếp tục.', 1);
