INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 36, '我要去埃及旅行。', 'Wǒ yào qù Āijí lǚxíng.', 'Tôi sẽ đi du lịch Ai Cập.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 36, '我已经办好了签证和护照。', 'Wǒ yǐjīng bànhǎole qiānzhèng hé hùzhào.', 'Tôi đã làm xong visa và hộ chiếu.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 36, '金字塔是世界历史奇迹。', 'Jīnzìtǎ shì shìjiè lìshǐ qíjì.', 'Kim tự tháp là kỳ tích lịch sử thế giới.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 36, '一个人旅行要小心一点儿。', 'Yí ge rén lǚxíng yào xiǎoxīn yìdiǎnr.', 'Du lịch một mình phải cẩn thận hơn.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 36, '去埃及旅行', 'qù Āijí lǚxíng', 'đi du lịch Ai Cập', 0);
