INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 36, 1, '朱云', '听说你要去埃及？', 'Tīngshuō nǐ yào qù Āijí?', 'Nghe nói bạn sắp đi Ai Cập?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 36, 1, '马丁', '对，我一直想去看金字塔，这是我的旅行计划。', 'Duì, wǒ yìzhí xiǎng qù kàn jīnzìtǎ, zhè shì wǒ de lǚxíng jìhuà.', 'Đúng vậy, tôi luôn muốn đi xem kim tự tháp, đây là kế hoạch du lịch của tôi.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 36, 1, '朱云', '路上要小心一点儿。', 'Lùshang yào xiǎoxīn yìdiǎnr.', 'Trên đường phải cẩn thận nhé.', 2);
