INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 37, '这里的变化比我想的还大。', 'Zhèlǐ de biànhuà bǐ wǒ xiǎng de hái dà.', 'Sự thay đổi ở đây còn lớn hơn tôi nghĩ.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 37, '熟悉的地方现在变得有点儿陌生了。', 'Shúxī de dìfang xiànzài biàn de yǒudiǎnr mòshēng le.', 'Nơi quen thuộc giờ trở nên hơi xa lạ.', 2);
