INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 41, '对...来说 - đối với...mà nói', '对外国人来说，声调很难。', 'Đối với người nước ngoài mà nói, thanh điệu rất khó.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 41, '把+A+V成+B - biến A thành B', '他把枕头说成了针头。', 'Anh ấy đã nói nhầm ''gối'' thành ''đầu kim''.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 41, 'Câu phản vấn (1)', '这怎么会是针头呢？', 'Cái này sao lại là đầu kim được chứ?', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 41, '他说的是"枕头"，不是"针头"。', 'Tā shuō de shì "zhěntou", bú shì "zhēntóu".', 'Anh ấy nói là “gối”, không phải “đầu kim”.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 41, '因为声调不对，造成了误会。', 'Yīnwèi shēngdiào bú duì, zàochéngle wùhuì.', 'Vì thanh điệu sai nên gây ra hiểu lầm.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 41, '这个笑话让大家都笑了。', 'Zhège xiàohua ràng dàjiā dōu xiào le.', 'Chuyện cười này khiến mọi người đều cười.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 41, '请你帮我纠正一下发音。', 'Qǐng nǐ bāng wǒ jiūzhèng yíxià fāyīn.', 'Xin bạn giúp tôi sửa lại phát âm một chút.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 41, '声调不对', 'shēngdiào bú duì', 'thanh điệu không đúng', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 41, '造成误会', 'zàochéng wùhuì', 'gây ra hiểu lầm', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 41, '纠正发音', 'jiūzhèng fāyīn', 'sửa phát âm', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 41, 1, '山田', '护士，我要一个枕头。', 'Hùshi, wǒ yào yí ge zhěntou.', 'Y tá ơi, tôi cần một cái gối.', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 41, 1, '护士', '什么？针头？您没生病要打针啊？', 'Shénme? Zhēntóu? Nín méi shēngbìng yào dǎzhēn a?', 'Gì cơ? Đầu kim? Ngài không ốm sao cần tiêm?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 41, 1, '山田', '不是针头，是枕头，睡觉用的枕头！', 'Bú shì zhēntóu, shì zhěntou, shuìjiào yòng de zhěntou!', 'Không phải đầu kim, là cái gối, gối để ngủ ấy!', 2);
