INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 42, '除了...(以外)，... - ngoài...ra', '除了学习，他还喜欢运动。', 'Ngoài học tập ra, anh ấy còn thích thể thao.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 42, '不是A就是B - không A thì B', '他不是看书就是写信。', 'Anh ấy không đọc sách thì viết thư.', 1);
