INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 42, '中国来信改变了我的生活。', 'Zhōngguó láixìn gǎibiànle wǒ de shēnghuó.', 'Lá thư từ Trung Quốc đã thay đổi cuộc đời tôi.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 42, '除了学习汉语，我还了解了中国文化。', 'Chúle xuéxí Hànyǔ, wǒ hái liǎojiěle Zhōngguó wénhuà.', 'Ngoài học tiếng Hán, tôi còn hiểu thêm về văn hóa Trung Quốc.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 42, '这封信让我很感动。', 'Zhè fēng xìn ràng wǒ hěn gǎndòng.', 'Lá thư này khiến tôi rất cảm động.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 42, '我们一直保持着联系。', 'Wǒmen yìzhí bǎochízhe liánxì.', 'Chúng tôi vẫn luôn giữ liên lạc.', 3);
