INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 43, '这是我第一次打的。', 'Zhè shì wǒ dì-yī cì dǎdī.', 'Đây là lần đầu tiên tôi đi taxi.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 43, '路上堵车，我有点儿紧张。', 'Lùshang dǔchē, wǒ yǒudiǎnr jǐnzhāng.', 'Đường tắc, tôi hơi hồi hộp.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 43, '幸好司机走的路线很安全。', 'Xìnghǎo sījī zǒu de lùxiàn hěn ānquán.', 'May mà tuyến đường tài xế đi rất an toàn.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 43, '请问，到机场多少钱？', 'Qǐngwèn, dào jīchǎng duōshao qián?', 'Xin hỏi, đến sân bay bao nhiêu tiền?', 3);
