INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 43, 1, '马丁', '师傅，去火车站多少钱？', 'Shīfu, qù huǒchēzhàn duōshao qián?', 'Bác tài ơi, đến ga tàu bao nhiêu tiền?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 43, 1, '司机', '大概三十块，不过现在堵车，可能要贵一点儿。', 'Dàgài sānshí kuài, búguò xiànzài dǔchē, kěnéng yào guì yìdiǎnr.', 'Khoảng ba mươi đồng, nhưng giờ tắc đường, có thể sẽ đắt hơn chút.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 43, 1, '马丁', '好的，麻烦您了。', 'Hǎo de, máfan nín le.', 'Vâng, phiền bác.', 2);
