INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 44, 'A是A,但(是)/可(是)/就是...', '路是远，但是信鸽还是飞回来了。', 'Đường thì xa, nhưng bồ câu vẫn bay về được.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 44, 'Câu bị động không dấu hiệu', '信鸽训练好了。', 'Bồ câu đã được huấn luyện xong.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 44, '当...的时候 - khi...', '当信鸽飞回来的时候，大家都很惊讶。', 'Khi bồ câu bay về, mọi người đều ngạc nhiên.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 44, '这只信鸽飞了很远的距离才回来。', 'Zhè zhī xìngē fēile hěn yuǎn de jùlí cái huílái.', 'Con bồ câu này bay một quãng đường rất xa mới về được.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 44, '信鸽靠本能认路，真神奇。', 'Xìngē kào běnnéng rènlù, zhēn shénqí.', 'Bồ câu dựa vào bản năng để nhận đường, thật kỳ diệu.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 44, '经过训练，它能准确地飞回家。', 'Jīngguò xùnliàn, tā néng zhǔnquè de fēi huíjiā.', 'Qua huấn luyện, nó có thể bay về nhà một cách chính xác.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 44, '这真是一个奇迹。', 'Zhè zhēnshi yí ge qíjì.', 'Đây thực sự là một kỳ tích.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 44, '飞回来', 'fēi huílái', 'bay về', 0);
