INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 45, '他把表拨快三分钟，这样就不会迟到了。', 'Tā bǎ biǎo bō kuài sān fēnzhōng, zhèyàng jiù bú huì chídào le.', 'Anh ấy vặn đồng hồ nhanh lên ba phút, như vậy sẽ không đến muộn.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 45, '为了准时，他养成了提前出门的习惯。', 'Wèile zhǔnshí, tā yǎngchéngle tíqián chūmén de xíguàn.', 'Để đúng giờ, anh ấy đã tạo thói quen ra khỏi nhà sớm.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 45, '难道这个方法真的有用吗？', 'Nándào zhège fāngfǎ zhēnde yǒuyòng ma?', 'Chẳng lẽ phương pháp này thật sự có tác dụng sao?', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 45, '他总是很准时。', 'Tā zǒngshì hěn zhǔnshí.', 'Anh ấy luôn luôn đúng giờ.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 45, '拨快三分钟', 'bō kuài sān fēnzhōng', 'vặn nhanh ba phút', 0);
