INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 45, '难道...吗', 'nándào...ma', 'chẳng lẽ...sao', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 45, 1, '朱云', '你怎么每次都这么准时？', 'Nǐ zěnme měicì dōu zhème zhǔnshí?', 'Sao lần nào bạn cũng đúng giờ vậy?', 0);
