INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 46, '尽管...,但(是)/可(是)/却...', '尽管迟到了，他却还是很开心。', 'Mặc dù đến muộn, anh ấy vẫn rất vui.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 46, '到底 - rốt cuộc', '他到底来不来？', 'Rốt cuộc anh ấy có đến hay không?', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 46, '我们约好六点见面。', 'Wǒmen yuēhǎo liù diǎn jiànmiàn.', 'Chúng tôi đã hẹn gặp nhau lúc sáu giờ.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 46, '尽管等了很久，她却一直没来。', 'Jǐnguǎn děngle hěn jiǔ, tā què yìzhí méi lái.', 'Mặc dù đã đợi rất lâu, cô ấy vẫn không đến.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 46, '你到底来不来约会？', 'Nǐ dàodǐ lái bu lái yuēhuì?', 'Rốt cuộc bạn có đến buổi hẹn không?', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 46, '第一次约会，我很紧张。', 'Dì-yī cì yuēhuì, wǒ hěn jǐnzhāng.', 'Lần hẹn đầu tiên, tôi rất hồi hộp.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 46, '约好见面', 'yuēhǎo jiànmiàn', 'hẹn gặp nhau', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 46, '到底来不来', 'dàodǐ lái bu lái', 'rốt cuộc có đến hay không', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 46, '很紧张', 'hěn jǐnzhāng', 'rất hồi hộp', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 46, 1, '林娜', '你到底来不来？我都等了半个小时了！', 'Nǐ dàodǐ lái bu lái? Wǒ dōu děngle bàn ge xiǎoshí le!', 'Rốt cuộc bạn có đến không? Tôi đợi nửa tiếng rồi đấy!', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 46, 1, '阿明', '对不起，尽管我很想早点儿到，却因为堵车迟到了。', 'Duìbuqǐ, jǐnguǎn wǒ hěn xiǎng zǎodiǎnr dào, què yīnwèi dǔchē chídào le.', 'Xin lỗi, mặc dù tôi rất muốn đến sớm, nhưng vì tắc đường nên đến muộn.', 1);
