INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 47, '来 biểu thị số phỏng chừng', '电影院里坐了三十来个人。', 'Trong rạp có khoảng ba mươi người.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 47, '盲人朋友是靠听声音"看"电影的。', 'Mángrén péngyou shì kào tīng shēngyīn "kàn" diànyǐng de.', 'Người bạn khiếm thị ''xem'' phim bằng cách nghe âm thanh.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 47, '即使看不见画面，他也能想象出情节。', 'Jíshǐ kàn bu jiàn huàmiàn, tā yě néng xiǎngxiàng chū qíngjié.', 'Dù không nhìn thấy hình ảnh, anh ấy vẫn có thể tưởng tượng ra tình tiết.', 1);
