INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 47, '他听得很认真，好像真的看见了似的。', 'Tā tīng de hěn rènzhēn, hǎoxiàng zhēnde kànjiànle shìde.', 'Anh ấy nghe rất chăm chú, giống như thật sự đã nhìn thấy vậy.', 3);
