INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 50, '不管...都/也... - bất kể...đều...', '不管多难，愚公都要把山移走。', 'Bất kể khó khăn thế nào, Ngu Công đều muốn dời núi đi.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 50, '..., 再说... - huống chi', '山这么大，再说我们人这么少，怎么移？', 'Núi to như vậy, huống chi người chúng ta lại ít, làm sao dời được?', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 50, 'V+到底 - làm đến cùng', '愚公决心把移山做到底。', 'Ngu Công quyết tâm dời núi đến cùng.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 50, '愚公移山是一个有名的中国故事。', 'Yúgōng yíshān shì yí ge yǒumíng de Zhōngguó gùshi.', 'Ngu Công dời núi là một câu chuyện nổi tiếng của Trung Quốc.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 50, '不管别人怎么笑话他，愚公都不放弃。', 'Bùguǎn biéren zěnme xiàohua tā, Yúgōng dōu bú fàngqì.', 'Bất kể người khác cười nhạo thế nào, Ngu Công đều không từ bỏ.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 50, '他相信子孙后代能把山移走。', 'Tā xiāngxìn zǐsūn hòudài néng bǎ shān yízǒu.', 'Ông tin rằng con cháu đời sau có thể dời được núi.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 50, '坚持不懈才能成功。', 'Jiānchí búxiè cái néng chénggōng.', 'Kiên trì không ngừng mới có thể thành công.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 50, '愚公移山', 'Yúgōng yíshān', 'Ngu Công dời núi', 0);
