INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 51, '不必 - không cần', '现在不必带现金了。', 'Bây giờ không cần mang tiền mặt nữa.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 51, '只要...就... - chỉ cần...thì...', '只要有一张卡，就能坐车、买东西。', 'Chỉ cần có một tấm thẻ là có thể đi xe, mua đồ.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 51, '既然...就... - đã như vậy thì...', '既然卡这么方便，我们就用卡吧。', 'Đã tiện như vậy thì chúng ta dùng thẻ thôi.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 51, '现在用卡很方便，不必带很多现金。', 'Xiànzài yòng kǎ hěn fāngbiàn, búbì dài hěn duō xiànjīn.', 'Bây giờ dùng thẻ rất tiện, không cần mang nhiều tiền mặt.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 51, '只要刷一下卡，就能上车。', 'Zhǐyào shuā yíxià kǎ, jiù néng shàngchē.', 'Chỉ cần quẹt thẻ một cái là có thể lên xe.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 51, '我的公交卡该充值了。', 'Wǒ de gōngjiāokǎ gāi chōngzhí le.', 'Thẻ xe buýt của tôi cần nạp tiền rồi.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 51, '既然你有信用卡，就不用带现金了。', 'Jìrán nǐ yǒu xìnyòngkǎ, jiù búyòng dài xiànjīn le.', 'Đã có thẻ tín dụng rồi thì không cần mang tiền mặt nữa.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 51, '刷卡', 'shuākǎ', 'quẹt thẻ', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 51, '公交卡充值', 'gōngjiāokǎ chōngzhí', 'nạp tiền thẻ xe buýt', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 51, '不必带现金', 'búbì dài xiànjīn', 'không cần mang tiền mặt', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 51, 1, '山田', '坐公交车要带现金吗？', 'Zuò gōngjiāochē yào dài xiànjīn ma?', 'Đi xe buýt có cần mang tiền mặt không?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 51, 1, '朱云', '不必，只要有公交卡就能上车，很方便。', 'Búbì, zhǐyào yǒu gōngjiāokǎ jiù néng shàngchē, hěn fāngbiàn.', 'Không cần, chỉ cần có thẻ xe buýt là lên được, rất tiện.', 1);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 52, '低碳', 'dītàn', 'ít carbon (phát thải thấp)', 'low-carbon', 0);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 52, '环保', 'huánbǎo', 'bảo vệ môi trường', 'environmental protection', 1);
