INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 52, 'V+起来+đánh giá', '低碳生活做起来并不难。', 'Sống ít carbon làm ra thì không khó.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 52, '怎么也/都+V+不+kết quả', '怎么也改不了浪费的习惯。', 'Thế nào cũng không sửa được thói quen lãng phí.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 52, '连...都/也... - thậm chí...cũng...', '连一张纸我也舍不得浪费。', 'Thậm chí một tờ giấy tôi cũng không nỡ lãng phí.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 52, '我一直坚持"低碳生活"。', 'Wǒ yìzhí jiānchí "dītàn shēnghuó".', 'Tôi luôn kiên trì lối sống ''ít carbon''.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 52, '骑车上班既环保又健康。', 'Qíchē shàngbān jì huánbǎo yòu jiànkāng.', 'Đi xe đạp đi làm vừa bảo vệ môi trường vừa khỏe mạnh.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 52, '垃圾分类可以节约资源。', 'Lājī fēnlèi kěyǐ jiéyuē zīyuán.', 'Phân loại rác có thể tiết kiệm tài nguyên.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 52, '每个人都应该减少浪费。', 'Měi ge rén dōu yīnggāi jiǎnshǎo làngfèi.', 'Mỗi người đều nên giảm bớt lãng phí.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 52, '低碳生活', 'dītàn shēnghuó', 'cuộc sống ít carbon', 0);
