INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 53, '用不着', 'yòngbuzháo', 'không cần đến', 'no need', 3);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 53, '坚持', 'jiānchí', 'kiên trì', 'to persist', 4);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 53, '爬', 'pá', 'leo, trèo', 'to climb', 5);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 53, '陪', 'péi', 'đi cùng, tháp tùng', 'to accompany', 6);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 53, '体力', 'tǐlì', 'thể lực', 'physical strength', 7);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 53, '骄傲', 'jiāo''ào', 'tự hào', 'proud', 8);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 53, '台阶', 'táijiē', 'bậc thang', 'steps', 9);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 53, '哪怕...也... - dù cho...cũng...', '哪怕再累，他也要陪儿子爬完长城。', 'Dù có mệt đến mấy, ông cũng muốn đồng hành cùng con trai leo hết Trường Thành.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 53, '万一 - lỡ như', '万一体力不够，我们就休息一下。', 'Lỡ như thể lực không đủ, chúng ta nghỉ một chút.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 53, '用不着 - không cần đến', '这么近，用不着坐车。', 'Gần vậy, không cần đi xe.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 53, '父子俩一起爬长城。', 'Fùzǐ liǎ yìqǐ pá Chángchéng.', 'Hai cha con cùng leo Trường Thành.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 53, '哪怕很累，他也坚持爬到了最高处。', 'Nǎpà hěn lèi, tā yě jiānchí pádàole zuì gāo chù.', 'Dù rất mệt, anh ấy vẫn kiên trì leo đến điểm cao nhất.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 53, '万一走不动了，我们就休息一下。', 'Wànyī zǒu bu dòng le, wǒmen jiù xiūxi yíxià.', 'Lỡ như đi không nổi nữa thì chúng ta nghỉ một chút.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 53, '爬上长城，他感到很骄傲。', 'Pá shàng Chángchéng, tā gǎndào hěn jiāo''ào.', 'Leo lên được Trường Thành, anh ấy cảm thấy rất tự hào.', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 53, '父子俩', 'fùzǐ liǎ', 'hai cha con', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 53, '坚持爬到', 'jiānchí pádào', 'kiên trì leo đến', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 53, '感到骄傲', 'gǎndào jiāo''ào', 'cảm thấy tự hào', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 53, 1, '儿子', '爸爸，我们还要爬多久？', 'Bàba, wǒmen hái yào pá duōjiǔ?', 'Bố ơi, chúng ta còn phải leo bao lâu nữa?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 53, 1, '爸爸', '哪怕再累，我们也要爬到最高处，加油！', 'Nǎpà zài lèi, wǒmen yě yào pádào zuì gāo chù, jiāyóu!', 'Dù có mệt đến mấy, chúng ta cũng phải leo đến điểm cao nhất, cố lên!', 1);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '搭车', 'dāchē', 'đi nhờ xe', 'to hitchhike', 0);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '柏林', 'Bólín', 'Berlin', 'Berlin', 1);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '竟然', 'jìngrán', 'thế mà, lại', 'unexpectedly', 2);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '由', 'yóu', 'do, bởi', 'by', 3);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '陌生人', 'mòshēngrén', 'người lạ', 'stranger', 4);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '冒险', 'màoxiǎn', 'mạo hiểm', 'adventure, to take risks', 5);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '善良', 'shànliáng', 'tốt bụng', 'kind-hearted', 6);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '顺路', 'shùnlù', 'tiện đường', 'on the way', 7);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '经历', 'jīnglì', 'trải nghiệm', 'experience', 8);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, order_index) VALUES (12, 54, '难忘', 'nánwàng', 'khó quên', 'unforgettable', 9);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 54, '竟然 - thế mà, lại', '他竟然一分钱都没花就到了柏林。', 'Anh ấy thế mà không tốn một xu nào đã đến được Berlin.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 54, 'Câu chữ 由 - do, bởi', '这次旅行完全由陌生人的帮助完成。', 'Chuyến đi này hoàn toàn được hoàn thành nhờ sự giúp đỡ của người lạ.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, example_zh, example_vi, order_index) VALUES (12, 54, '一+V/Adj - vừa mới...', '他一路搭车，一路认识新朋友。', 'Anh ấy vừa đi nhờ xe, vừa quen thêm bạn mới trên đường.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 54, '他决定搭车去柏林。', 'Tā juédìng dāchē qù Bólín.', 'Anh ấy quyết định đi nhờ xe đến Berlin.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 54, '路上遇到了很多善良的陌生人。', 'Lùshang yùdàole hěn duō shànliáng de mòshēngrén.', 'Trên đường anh ấy gặp rất nhiều người lạ tốt bụng.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 54, '这是一次难忘的冒险经历。', 'Zhè shì yí cì nánwàng de màoxiǎn jīnglì.', 'Đây là một trải nghiệm mạo hiểm khó quên.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 54, '竟然一分钱都没花就到了目的地。', 'Jìngrán yì fēn qián dōu méi huā jiù dàole mùdìdì.', 'Thế mà không tốn một xu nào cũng đã đến được đích.', 3);
